- name: Render nginx site
  ansible.builtin.template:
    src: site.conf.j2
    dest: /etc/nginx/sites-available/app.conf
    validate: nginx -t -c %s
  notify: Reload nginx

# templates/site.conf.j2
server {
  listen {{ app_port | default(80) }};
{% for name in server_names %}
  server_name {{ name }};
{% endfor %}
}

